const store = $json.store === undefined ? 'live' : String($json.store);
const version = String($json.version ?? '');
if (!/^(live|fixture-[a-z0-9-]{1,40})$/.test(store)) throw new Error('invalid-request: unknown store');
if (!/^substack:[a-z0-9-]+:\d{1,15}@sha256:[0-9a-f]{64}$/.test(version)) throw new Error('invalid-request: not a source version ID');
return { json: { store, version } };

// ---- shared: source-bundle-v1 canonical form (doc/experiments/n8n-vs-mastra.md) ----
const crypto = require('crypto');
// RFC 8785 for the value shapes a bundle holds: keys sorted by UTF-16 code units, no whitespace.
const canonicalize = (v) => {
  if (v === null || typeof v === 'string' || typeof v === 'boolean') return JSON.stringify(v);
  if (typeof v === 'number') { if (!Number.isFinite(v)) throw new Error('canonicalize: non-finite number'); return JSON.stringify(v); }
  if (Array.isArray(v)) return '[' + v.map(canonicalize).join(',') + ']';
  if (typeof v === 'object') {
    const e = Object.entries(v).filter(([, x]) => x !== undefined);
    e.sort(([a], [b]) => (a < b ? -1 : a > b ? 1 : 0));
    return '{' + e.map(([k, x]) => JSON.stringify(k) + ':' + canonicalize(x)).join(',') + '}';
  }
  throw new Error('canonicalize: unsupported ' + typeof v);
};
const sha256 = (s) => crypto.createHash('sha256').update(s, 'utf8').digest('hex');
const BUNDLE_KEYS = ['audience', 'author', 'item', 'mediaUploadId', 'medium', 'postId', 'publishedAt', 'schema', 'slug', 'text', 'textSource', 'title', 'updatedAt', 'url'];
const strOrNull = (v) => v === null || typeof v === 'string';
// The same shape rules as the Mastra track's SourceBundleSchema; anything else is refused.
const validateBundle = (b) => {
  const ok = b && typeof b === 'object' && !Array.isArray(b)
    && JSON.stringify(Object.keys(b).sort()) === JSON.stringify(BUNDLE_KEYS)
    && b.schema === 'source-bundle-v1'
    && typeof b.item === 'string' && /^substack:[a-z0-9-]+:\d{1,15}$/.test(b.item)
    && typeof b.postId === 'string' && /^\d{1,15}$/.test(b.postId)
    && typeof b.slug === 'string' && /^[a-z0-9-]{1,200}$/.test(b.slug)
    && typeof b.url === 'string' && /^https:\/\/[a-z0-9.-]+\/p\/[a-z0-9-]{1,200}$/.test(b.url)
    && typeof b.title === 'string' && b.title.length <= 1000
    && strOrNull(b.publishedAt) && strOrNull(b.updatedAt) && strOrNull(b.author)
    && ['audio', 'video', 'written', 'unknown'].includes(b.medium)
    && typeof b.audience === 'string' && strOrNull(b.mediaUploadId)
    && ['supplied-transcript', 'article-html'].includes(b.textSource)
    && typeof b.text === 'string' && b.text.length <= 2000000;
  if (!ok) throw new Error('invalid-bundle: not a valid source-bundle-v1');
  return b;
};
// Parses stored or imported bytes and proves they are canonical and match the version ID.
const verifyBytes = (bytes, version) => {
  let b;
  try { b = JSON.parse(bytes); } catch { throw new Error('hash-mismatch: bundle bytes are not JSON'); }
  validateBundle(b);
  if (canonicalize(b) !== bytes) throw new Error('hash-mismatch: bundle bytes are not canonical');
  const hex = sha256(bytes);
  if (version !== undefined && version !== `${b.item}@sha256:${hex}`) throw new Error('hash-mismatch: bytes do not reproduce the version ID');
  return { bundle: b, sha256: hex, version: `${b.item}@sha256:${hex}` };
};
// ---- end shared ----
// The pinned input for a writing run: read from storage only, never refetched, and verified.
const req = $('Validate').item.json;
const r = $json.result;
if (!r) throw new Error(`not-found: no source version ${req.version}`);
const v = verifyBytes(r.bundleBytes, req.version);
return { json: { store: req.store, version: v.version, sha256: v.sha256, bundle: v.bundle, warnings: r.warnings, capturedAt: r.capturedAt } };
